interface Outbox<T> {
  append(e: Envelope<T>): Promise<void>;      // resolves only when durable
  claim(n: number): Promise<Row<T>[]>;
  ack(id: string): Promise<void>;             // called after the peer ack
}
export async function relay<T>(store: Outbox<T>, send: (p: T) => Promise<void>) {
  for (const row of await store.claim(32)) {
    await send(row.payload);                  // throws -> the row stays pending
    await store.ack(row.id);
  }
}
